CREATE TABLE `t_project`  (
  `c_projectCode` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '项目编码',
  `c_projectName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '项目名称',
  `c_descPath` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述路径',
  `c_opCode` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作人员编码',
  `c_date` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '项目日期',
  `c_time` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '项目时间',
  `c_mark` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标记信息',
  `c_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `c_digWay` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开挖方式',
  `c_beginTime` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开始时间',
  `c_endTime` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '结束时间',
  `c_totalEvp` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '总估值',
  `c_lithology` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岩性',
  PRIMARY KEY (`c_projectCode`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_project
-- ----------------------------

-- ----------------------------
-- Table structure for t_rockdesc
-- ----------------------------
DROP TABLE IF EXISTS `t_rockdesc`;
CREATE TABLE `t_rockdesc`  (
  `c_craterNo` int NOT NULL COMMENT '爆坑编号',
  `c_craterShape` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '爆坑形状（V形/浅窝形/平滑形/凹形）',
  `c_craterPole` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '爆坑极限位置',
  `c_craterPosition` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '爆坑实际位置',
  `c_craterSize` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '爆坑尺寸',
  `c_features` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '爆破特征（松脱/剥落/弹射/抛掷）',
  `d_maxDistance` decimal(6, 2) NULL DEFAULT NULL COMMENT '最大飞散距离',
  `d_SectionalArea` decimal(6, 2) NULL DEFAULT NULL COMMENT '爆坑横截面积',
  `d_craterBulk` decimal(6, 2) NULL DEFAULT NULL COMMENT '爆坑体积',
  `d_maxDepth` decimal(6, 2) NULL DEFAULT NULL COMMENT '爆坑最大深度',
  `c_rockShape` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岩石形态（散体状/薄片/板状）',
  `c_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `c_caseCode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '案件编码',
  `c_mark` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标记信息',
  PRIMARY KEY (`c_caseCode`, `c_craterNo`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_rockdesc
-- ----------------------------

-- ----------------------------
-- Table structure for t_stress
-- ----------------------------
DROP TABLE IF EXISTS `t_stress`;
CREATE TABLE `t_stress`  (
  `d_terrain` decimal(6, 2) NULL DEFAULT NULL COMMENT '地层类别（初喷混凝土，锚杆，钢筋网，复喷混凝土，钢拱架/TH梁，衬砌）',
  `d_azimuth1` decimal(6, 2) NULL DEFAULT NULL COMMENT '第一主应力方向的方位角（单位：度）',
  `c_plunge1` decimal(6, 2) NULL DEFAULT NULL COMMENT '第一主应力方向的倾角（单位：度）',
  `d_size1` decimal(6, 2) NULL DEFAULT NULL COMMENT '第一主应力的大小（单位：MPa）初喷混凝土，锚杆，钢筋网，复喷混凝土，钢拱架/TH梁，衬砌',
  `d_azimuth2` decimal(6, 2) NULL DEFAULT NULL COMMENT '第二主应力方向的方位角（单位：度）',
  `c_plunge2` decimal(6, 2) NULL DEFAULT NULL COMMENT '第二主应力方向的倾角（单位：度）',
  `d_size2` decimal(6, 2) NULL DEFAULT NULL COMMENT '第二主应力的大小（单位：MPa）（初喷混凝土，锚杆，钢筋网，复喷混凝土，钢拱架/TH梁，衬砌）',
  `d_azimuth3` decimal(6, 2) NULL DEFAULT NULL COMMENT '第三主应力方向的方位角（单位：度）',
  `c_plunge3` decimal(6, 2) NULL DEFAULT NULL COMMENT '第三主应力方向的倾角（单位：度）',
  `d_size3` decimal(6, 2) NULL DEFAULT NULL COMMENT '第三主应力的大小（单位：MPa）（初喷混凝土，锚杆，钢筋网，复喷混凝土，钢拱架/TH梁，衬砌）',
  `d_kangya` decimal(6, 2) NULL DEFAULT NULL COMMENT '抗压强度（单位：MPa）',
  `d_kangla` decimal(6, 2) NULL DEFAULT NULL COMMENT '抗拉强度（单位：MPa）',
  `d_strain` decimal(6, 2) NULL DEFAULT NULL COMMENT '变形量（初喷混凝土，锚杆，钢筋网，复喷混凝土，钢拱架/TH梁，衬砌）',
  `d_Brittleness` decimal(6, 2) NULL DEFAULT NULL COMMENT '脆性指数',
  `c_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `c_caseCode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '案件编码',
  `c_mark` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标记信息',
  PRIMARY KEY (`c_caseCode`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_stress
-- ----------------------------

-- ----------------------------
-- Table structure for t_support
-- ----------------------------
DROP TABLE IF EXISTS `t_support`;
CREATE TABLE `t_support`  (
  `c_supportType` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '支护类型（初喷混凝土，锚杆，钢筋网，复喷混凝土，钢拱架/TH梁，衬砌）\r\n',
  `c_supportTime` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '支护时间',
  `c_area` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '区域',
  `c_position` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '位置',
  `c_supportNum` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '支护编号',
  `c_parameter` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '参数',
  `c_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  `i_serialid` int NOT NULL AUTO_INCREMENT COMMENT '序号',
  `c_caseCode` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '案例编码',
  `c_mark` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标记信息',
  PRIMARY KEY (`i_serialid`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 99 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

