-- ----------------------------
-- Table structure for t_waveproject
-- ----------------------------
DROP TABLE IF EXISTS `t_waveproject`;
CREATE TABLE `t_waveproject`  (
  `i_serialid` int NOT NULL AUTO_INCREMENT COMMENT '序号',
  `c_projectName` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '项目名称',
  `c_digWay` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开挖方式',
  `c_lithology` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '岩性',
  `c_wzSystem` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '监测系统',
  `c_rate` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '监测频率',
  `i_sensor` int NULL DEFAULT NULL COMMENT '传感器数量',
  `c_sensorWay` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '传感器安装方式',
  `c_waveSort` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '波形类型',
  `c_descPath` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述文件路径',
  `c_opCode` varchar(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '操作代码',
  `c_date` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '日期',
  `c_time` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '时间',
  `c_mark` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标记信息',
  `c_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  PRIMARY KEY (`i_serialid`) USING BTREE,
  UNIQUE INDEX `IX_T_waveProject`(`i_serialid` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_waveproject
-- ----------------------------

-- ----------------------------
-- Table structure for t_waveproperty
-- ----------------------------
DROP TABLE IF EXISTS `t_waveproperty`;
CREATE TABLE `t_waveproperty`  (
  `i_serialid` int NOT NULL COMMENT '序号',
  `c_waveName` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '波姓名称',
  `c_sensorSort` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '传感器类别',
  `c_sensorWay` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '传感器安装方式',
  `i_PWave` int NULL DEFAULT NULL COMMENT 'P波数量',
  `i_SWave` int NULL DEFAULT NULL COMMENT 'S波数量',
  `i_vibration` int NULL DEFAULT NULL COMMENT '振动次数',
  `c_ringRate` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '振铃率',
  `c_maxSwing` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最大摆幅',
  `i_swingPosition` int NULL DEFAULT NULL COMMENT '摆幅位置',
  `c_PWaveValue` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'P波值',
  `c_mainRate` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '主频率',
  `img_waveFile` blob NULL COMMENT '波形文件',
  `c_mark` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标记信息',
  `c_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注信息',
  PRIMARY KEY (`i_serialid`, `c_waveName`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_waveproperty
-- ----------------------------

