INSERT INTO `t_casedesc` VALUES ('即时型', '应变型', '轻微', '上午8点30分左右，快出完渣时发生岩爆，后挖机返回岩爆位置进行排险，排险过程无岩爆，无声响', NULL, '1', 'BY-CP-201708170830-S', '围岩表面偶有清脆撕裂声', '轻微粉尘', NULL, '不发育', '未风化', '完整性好', '不发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '应变型', '轻微', '12月1日14点50分左右于掌子面后方DK200+091处右拱肩发生轻微岩爆，持续时间约20分钟，岩爆过程伴有响声和粉尘。围岩偶有爆裂声响。', NULL, '1', 'BY-CZ-201712011500-S', '伴有撕裂声', '围岩爆裂时，伴有岩粉喷射现象，快速充满开挖空间，能见度低', NULL, '不发育', '未风化', '完整性好', '一般发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '结构面滑移型', '轻微', '2017年12月15日17点40分于掌子面后面右侧拱肩DK200+038处发生轻微岩爆，岩爆期间偶有响声，并伴有粉尘，有薄片状岩体剥落。', NULL, '1', 'BY-CZ-201712151740-S', '围岩表面有清脆的撕裂声', '伴有大量粉尘', NULL, '不发育', '微风化', '完整性差', '很发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '应变型', '轻微', '出渣完成后发生岩爆，岩块脱落，爆出浅坑，其后对岩爆位置进行处理，处理过程中无岩爆发生，也无声响及掉块现象。', NULL, '1', 'BY-CZ-201805291110-S', NULL, NULL, NULL, '不发育', '未风化', '完整性好', '不发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '应变型', '轻微', '2016年6月3日上午8点50分左右，掌子面拍先后南侧围岩与掌子面交界处发生轻微岩爆，有明显响声，岩块持续脱落，爆出浅坑，其后对岩爆位置进行处理', NULL, '1', 'BY-CZ-201806030850-S', '围岩表面有清脆撕裂声', '粉尘较大', NULL, '不发育', '微风化', '完整性好', '不发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '应变型', '轻微', '2018年6月4日下午16时50分左右，掌子面北侧发生岩爆，有明显响声，岩块持续脱落，爆出浅坑，其后对岩爆位置进行处理，处理过程中无岩爆发生，也无声响及掉块现象。', NULL, '1', 'BY-CZ-201806041650-S', '围岩表面有清脆撕裂声', '岩爆时伴有粉尘喷射现象，快速充满开挖空间', NULL, '不发育', '微风化', '完整性好', '不发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '应变型', '中等', '6月7日凌晨1：50左右，出渣完成，准备打钻时发生岩爆，持续时间约30分钟左右，声响明显，呈间歇性', NULL, '1', 'BY-CZ-201806070150-M', NULL, '存在大量粉尘，能见度迅速降低', NULL, '不发育', '未风化', '完整性好', '不发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '应变型', '轻微', 'DK199+494~490洞段北侧围岩拱腰处发生轻微岩爆，岩爆持续时间约20分钟，伴有响声和粉尘 ', NULL, '1', 'BY-CZ-201806132032-S', '围岩表面有清脆的撕裂声，似鞭炮声，偶有爆裂声响。', '围岩爆裂时，伴有岩粉喷射现象，快速充满开挖空间，能见度低。', NULL, '不发育', '微风化', '完整性一般', '一般发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '结构面滑移型', '中等', '爆破后10分钟左右发生主爆，之后进行排险出渣，爆坑中继续产生声响及掉块，暂停出渣，掉块平静后继续出渣，之后喷浆封闭掌子面及边墙。', NULL, '1', 'BY-JP-2017042118-M', '清脆撕裂声', '很多，能见度低', NULL, '不发育', '未风化', '较完整', '较发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '结构面滑移型', '中等', '12横正洞10月05日6点30左右响炮，出渣、排险正常施工，11点左右拱顶偏北以及掌子面南侧与围岩交接处发生岩爆，时有块状、片状岩块弹射掉落，弹射最大距离约1m，到15点左右，开始喷浆、打锚杆进行支护。', NULL, '1', 'BY-JP-2018100511-M', '较大清脆响声', '粉尘大，密度高', NULL, '不发育', '未', '完整', '较发育', NULL);
INSERT INTO `t_casedesc` VALUES ('时滞型', '应变型', '中等', '12横正洞10月05日6时30分响炮，出渣、排险正常施工，11点左右拱顶偏北以及掌子面南侧与围岩交接处发生岩爆，时有块状、片状岩块弹射掉落，弹射最大距离约1m，到16点左右，掌子面后方25-50m区域北侧围岩发生岩爆，等待后排险，到20点左右排险结束，掌子面开始打锚杆进行支护。', NULL, '1', 'BY-JP-2018100516-M', '边墙脱落，声响小', '较小', NULL, '不发育', '微风化', '完整', '不发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '应变型', '中等', '12横正洞10月08日09时50分左右响炮，出渣、排险正常施工，13点左右拱顶附近发生岩爆，时有片状岩块及碎渣掉落，停工等待后排险，再等待，到18点左右基本稳定，掌子面开始喷浆打锚杆进行支护。', NULL, '1', 'BY-JP-2018100813-M', '清脆声响', '很多', NULL, '不发育', '未风化', '完整', '较发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '应变型', '强烈', '12横正洞10月10日21时17分左右响炮，出渣、排险正常施工，00:30点左右拱顶附近开始发生轻微岩爆，然后排险，等待后有掉块和声响。再排险如此循环，8点左右再次排险后发生中等岩爆，持续有片状岩块及碎渣掉落，声响较大，继续停工等待后排险，再等待，到12点左右基本稳定，掌子面开始喷浆打锚杆进行支护。16点左右电线挂断，洞内停工，20点左右恢复供电，继续打锚杆，喷浆。', NULL, '1', 'BY-JP-2018101101-M', '清脆及闷响', '较多', NULL, '不发育', '未风化', '完整', '不发育', NULL);
INSERT INTO `t_casedesc` VALUES ('时滞型', '应变型', '中等', '12横正洞10月14日16时10分左右响炮，出渣、排险正常施工，19点左右拱顶偏北开始发生岩爆，然后等待后，掌子面后方北侧围岩5-15m区域发生大面积剥落。然后排险、等待，有持续响声、掉块及弹射现象。10月15日8时30分左右掌子面至后方5m区域北侧围岩发生岩爆，大面积剥落岩块。到9点左右基本稳定，掌子面开始准备喷浆打锚杆进行支护。', NULL, '1', 'BY-JP-2018101419-M', '持续声响，不大', '较多', NULL, '不发育', '未风化', '完整', '较发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '结构面滑移型', '中等', '早上6:00喷浆后准备打钻时发生岩爆。岩爆位置主要在正洞左侧拱肩至拱顶。岩爆持续时间较久，但爆出的岩石块体较小。11点排险扒渣，但排险后仍有较大响声并伴随小块体爆出。扒渣后在掌子面附近左侧拱肩至拱顶形成了较大的爆坑。爆坑面较光滑。', NULL, '1', 'BY-JZ-2017112006-M', '较大清脆声', '很多', NULL, '不发育', '未风化', '完整', '不发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '结构面滑移型', '强烈', NULL, NULL, '1', 'BY-JZ-2017112109-I', NULL, '很多', NULL, '不发育', '未风化', '较破碎', '发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '应变型', '强烈', '18日晚上22:00出完渣后准备喷浆时发生岩爆。岩爆位置主要在正洞左侧拱肩。岩爆持续时间较久，主爆岩块较大，同时伴随薄片状剥落岩体。排险后仍有较大响声并伴随小块体爆出。扒渣后在掌子面附近左侧拱肩形成了较大的爆坑。爆坑面较光滑。', NULL, '1', 'BY-JZ-2018041822-M', '似开挖爆破声', '很多', NULL, '不发育', '未风化', '较破碎', '发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '结构面滑移型', '中等', '12横正洞16点30左右响炮，由于掏槽眼未响炮，导致掌子面放炮后岩石未爆下来（仅出3车渣）。17点50左右准备全断面补炮时，掌子面后方6m左右范围内发生岩爆，不时有块状、板状岩块弹射掉落。前期主要以岩石滑移掉落为主，约21点左右响声较大，有较大块体爆落，块体最厚10cm左右。', NULL, '1', 'BY-JZ-2018061917-M', '似雷管爆破清脆声', '很多', NULL, '不发育', '未风化', '较完整', '较发育', NULL);
INSERT INTO `t_casedesc` VALUES ('时滞型', '结构面滑移型', '中等', '12横正洞24日22点30左右响炮，出渣、喷浆正常施工，25日3点左右掌子面前40米左右左侧围岩及顶拱发生岩爆，不时有块状、片状岩块弹射掉落。25日11点左右响炮，岩爆区域继续掉块，出渣后停工进行支护。', NULL, '1', 'BY-JZ-2018082503-M', '岩石滑落哗哗声', '较少', NULL, '不发育', '未风化', '较完整', '较发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '结构面滑移型', '中等', '12横正洞9月21日11点27响炮，出渣、喷浆正常施工，15点30左右掌子面右侧拱脚与围岩交接处发生岩爆，时有块状、片状岩块弹射掉落，到17点左右响声及掉块不明显，趋于稳定。随后停工进行支护。', NULL, '1', 'BY-JZ-2018092115-M', '清脆撕裂声', '较多', NULL, '不发育', '未风化', '较完整', '较发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '结构面滑移型', '中等', '12横正洞9月23日5点30左右响炮，出渣、喷浆正常施工，9点30左右掌子面南侧拱脚与围岩交接处发生岩爆，时有块状、片状岩块弹射掉落，到12点30左右，响声及掉块不再明显，趋于稳定。随后停工进行支护。', NULL, '1', 'BY-JZ-2018092310-M', '岩石撕裂及闷响声', '较多', NULL, '不发育', '未风化', '较完整', '较发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', NULL, '强烈', '2015年4月23日在5#实验室中导洞爬坡段至水平段南侧边墙中上部至拱肩部位发生强烈岩爆事件，即“4.23”岩爆。图1给出了“4.23”强烈岩爆破坏区形态，从破坏区形态上可将该岩爆划分为两个破坏区，两个区段桩号分别为0+012.5~0+032和0+035~0+045。破坏岩体形成块体不一，薄板/片状、小碎块状、大块体均有出现，其中I破坏区内岩爆块体更倾向于不规则块体，而II破坏区多为薄板或片状。', NULL, '1', 'JP-201504230800-I', '闷响', '大量粉尘', NULL, '不发育', '未风化', '较完整', '较发育', NULL);
INSERT INTO `t_casedesc` VALUES ('即时型', '结构面滑移型', '极强', '极强岩爆发生前，发生了数次中等及强烈岩爆。岩爆现场发现多达数十个大小不一、形状各异的爆坑，尤其左侧（紧邻S-697侧）拱脚最为严重，爆坑基本连续，可见的爆坑深度一般在1.5-2m，少数深度超过2m。', '', '1', 'NJ-96-201505312328-E', '', '', '', '无地下水发育', '未见风险，岩体新鲜', '岩体较完整', '', '');
INSERT INTO `t_casedesc` VALUES ('即时型', '应变型', '强烈', '有较大块体弹射塌落', NULL, '1', 'NJ-96-201602270758-I', '有巨大的沉闷声响', '岩爆发生时响声较大', NULL, '地下水不发育', '围岩未风化', '围岩较完整', '节理不发育', NULL);
